scripts.library_js:
// Inserts a note above the length limit and the state_delta reminder. Those two
// lines must stay last, because the model follows the text nearest its reply.
function insertBeforeTail(text, note) {
  var marks = ["\n\n[Hard limit:", "\n\n[Part of your last state_delta", "\n\n[Reminder: end your reply"];
  for (var i = 0; i < marks.length; i++) {
    var at = text.lastIndexOf(marks[i]);
    if (at !== -1) return text.slice(0, at) + "\n\n" + note + text.slice(at);
  }
  return text + "\n\n" + note;
}

scripts.input_js:
// Rolls a d20 for each do action, so the narrator has a reason to let an
// action fail.
const modifier = (text) => {
  // A say action also starts with "> You", so it is excluded by its own prefix.
  // Story actions do not start with "> You" and pass through unchanged.
  if (text.indexOf("> You ") !== 0 || text.indexOf("> You say") === 0) {
    return { text: text };
  }
  // An edited turn runs this hook again on text it already tagged. Remove the
  // earlier tag so the action never carries two. Keep its number, so that
  // editing a turn cannot reroll a failure.
  var old = text.match(/\s*\[d20: (\d+)\]\s*$/);
  // A tag that a player typed into the action sits before the closing period,
  // not at the end. Remove it so the player cannot choose the roll.
  var base = (old ? text.slice(0, old.index) : text).replace(/\s*\[d20:[^\]]*\]/g, "");
  var roll = old ? Number(old[1]) : Math.floor(Math.random() * 20) + 1;
  if (!(roll >= 1 && roll <= 20)) roll = Math.floor(Math.random() * 20) + 1;
  return { text: base + " [d20: " + roll + "]" };
};
modifier(text);

scripts.context_js:
// In playtests the narrator described the gift's cost but sent no focus or
// mastery change, and sometimes dropped a wound. A note next to the reply asks
// for that bookkeeping. When the player's action names the gift, the note asks
// for exact changes, because the model follows an exact number more reliably
// than a condition.
const modifier = (text) => {
  // Read the gift from the plot essentials. A blank answer means Mending.
  var m = text.match(/The gift the shrine gave the player: \[([^\]\n]*)\]/);
  var gift = (m && m[1].trim()) || "Mending";
  var word = (gift.toLowerCase().match(/[a-z]+/) || ["gift"])[0];
  // "Mending" must also match "mend", so drop a trailing "ing".
  if (word.length > 6 && /ing$/.test(word)) word = word.slice(0, -3);

  // Only the newest entry counts. On a continue it is the narrator's own text,
  // and an older action must not be charged twice.
  var last = history.length ? history[history.length - 1] : null;
  var action = last && /^> You /.test(last.text || "") ? last.text.toLowerCase() : "";
  var usesGift = action !== "" && (action.indexOf("gift") !== -1 || action.indexOf(word) !== -1);

  var note;
  if (usesGift) {
    note = "[Bookkeeping this turn: the player uses the gift. Include \"player.focus\" and \"player.mastery\" in your state_delta block: focus -2 and mastery 1 for a small use, or focus -5 and mastery 2 for a great use or an attempt beyond the gift's band. Double the focus cost on blighted ground. Mastery may reach 4 under real pressure. If the gift fails before it starts, send focus only.]";
  } else {
    note = "[Bookkeeping: report every wound as a negative \"player.hp\", every payment as a \"player.coin\" change, and any use of the gift as a negative \"player.focus\" with a \"player.mastery\" of 1 to 4.]";
  }
  return { text: insertBeforeTail(text, note) };
};
modifier(text);
